const searchFeedbacks = `-- name: SearchFeedbacks :many
SELECT 
    f.feedback_id,
    f.user_id,
    f.type,
    f.title,
    f.content,
    f.contact_email,
    f.submitted_at,
    f.status,
    u.username,
    u.nickname
FROM feedbacks f
LEFT JOIN users u ON f.user_id = u.user_id
WHERE f.title ILIKE '%' || $1 || '%' 
    OR f.content ILIKE '%' || $1 || '%'
ORDER BY f.submitted_at DESC
LIMIT $2 OFFSET $3
`

type SearchFeedbacksParams struct {
	Column1 sql.NullString `json:"column_1"`
	Limit   int32          `json:"limit"`
	Offset  int32          `json:"offset"`
}

type SearchFeedbacksRow struct {
	FeedbackID   string         `json:"feedback_id"`
	UserID       sql.NullString `json:"user_id"`
	Type         FeedbackType   `json:"type"`
	Title        string         `json:"title"`
	Content      string         `json:"content"`
	ContactEmail sql.NullString `json:"contact_email"`
	SubmittedAt  time.Time      `json:"submitted_at"`
	Status       sql.NullString `json:"status"`
	Username     sql.NullString `json:"username"`
	Nickname     sql.NullString `json:"nickname"`
}

// 搜索反馈（按标题和内容）
func (q *Queries) SearchFeedbacks(ctx context.Context, arg SearchFeedbacksParams) ([]SearchFeedbacksRow, error) {
	rows, err := q.query(ctx, q.searchFeedbacksStmt, searchFeedbacks, arg.Column1, arg.Limit, arg.Offset)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchFeedbacksRow{}
	for rows.Next() {
		var i SearchFeedbacksRow
		if err := rows.Scan(
			&i.FeedbackID,
			&i.UserID,
			&i.Type,
			&i.Title,
			&i.Content,
			&i.ContactEmail,
			&i.SubmittedAt,
			&i.Status,
			&i.Username,
			&i.Nickname,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateFeedbackStatus = `-- name: UpdateFeedbackStatus :one

UPDATE feedbacks 
SET status = $2
WHERE feedback_id = $1
RETURNING 
    feedback_id,
    user_id,
    type,
    title,
    content,
    contact_email,
    submitted_at,
    status
`

type UpdateFeedbackStatusParams struct {
	FeedbackID string         `json:"feedback_id"`
	Status     sql.NullString `json:"status"`
}

// =============================================
// 3. 反馈状态管理 (Feedback Status Management)
// =============================================
// 更新反馈状态
func (q *Queries) UpdateFeedbackStatus(ctx context.Context, arg UpdateFeedbackStatusParams) (Feedback, error) {
	row := q.queryRow(ctx, q.updateFeedbackStatusStmt, updateFeedbackStatus, arg.FeedbackID, arg.Status)
	var i Feedback
	err := row.Scan(
		&i.FeedbackID,
		&i.UserID,
		&i.Type,
		&i.Title,
		&i.Content,
		&i.ContactEmail,
		&i.SubmittedAt,
		&i.Status,
	)
	return i, err
}
